cat > /tmp/repro.py <<'EOF'
from fastapi import FastAPI, APIRouter, FastAPIError

def test_circular_router():
    router = APIRouter()
    try:
        router.include_router(router)
    except FastAPIError as exc:
        assert str(exc) == "A router cannot be included into itself"
        return

    assert False, "FastAPIError was not raised when including a router into itself"

if __name__ == "__main__":
    try:
        test_circular_router()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        exit(1)
EOF
python3 /tmp/repro.py; echo EXIT=$?

